{"version":3,"file":"dark-store-app.jsdbx","sources":["../../src/client/components/darkstore/DsHeader.tsx","../../src/client/dark-store-app.css","../../src/client/components/darkstore/DsHeader.css","../../src/client/components/darkstore/DsImpactStrip.css","../../src/client/components/darkstore/DsImpactStrip.tsx","../../src/client/components/darkstore/DsPulseHero.css","../../src/client/components/darkstore/DsPulseHero.tsx","../../src/client/components/darkstore/DsKpiCards.css","../../src/client/components/darkstore/DsKpiCards.tsx","../../src/client/components/darkstore/DsNetworkStatus.css","../../src/client/components/darkstore/DsNetworkStatus.tsx","../../src/client/components/darkstore/DsEquipmentHealth.css","../../src/client/components/darkstore/DsEquipmentHealth.tsx","../../src/client/components/darkstore/DsAiAssistant.css","../../src/client/components/darkstore/DsAiAssistant.tsx","../../src/client/components/darkstore/DsStaffGrid.css","../../src/client/components/darkstore/DsStaffGrid.tsx","../../src/client/components/darkstore/DsDeliveryOps.css","../../src/client/components/darkstore/DsDeliveryOps.tsx","../../src/client/components/darkstore/DsInventory.css","../../src/client/components/darkstore/DsInventory.tsx","../../src/client/components/darkstore/DsStoreHeatmap.css","../../src/client/components/darkstore/DsStoreHeatmap.tsx","../../src/client/components/darkstore/DsComplaints.css","../../src/client/components/darkstore/DsComplaints.tsx","../../src/client/components/darkstore/DsTimeline.css","../../src/client/components/darkstore/DsTimeline.tsx","../../src/client/components/darkstore/DsPredictive.css","../../src/client/components/darkstore/DsPredictive.tsx","../../src/client/components/darkstore/DsRisks.css","../../src/client/components/darkstore/DsRisks.tsx","../../src/client/components/darkstore/DsSystemStatus.css","../../src/client/components/darkstore/DsSystemStatus.tsx","../../src/client/dark-store-app.tsx"],"sourcesContent":["import React, { useState, useEffect } from 'react';
import './DsHeader.css';

export default function DsHeader() {
    const [time, setTime] = useState(new Date());

    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    const formatTime = (d: Date) =>
        d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });

    const formatDate = (d: Date) =>
        d.toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });

    return (
        <div className="ds-header ds-card">
            <div className="ds-header__left">
                <div className="ds-header__title-row">
                    <span className="ds-header__icon">🏪</span>
                    <h1 className="ds-header__title">Dark Store Intelligence Center</h1>
                </div>
                <p className="ds-header__subtitle">Real-Time Store Health &amp; Operational Intelligence</p>
            </div>
            <div className="ds-header__right">
                <div className="ds-header__live-badge">
                    <span className="ds-header__live-dot"></span>
                    <span>LIVE</span>
                </div>
                <div className="ds-header__time-block">
                    <span className="ds-header__time">{formatTime(time)}</span>
                    <span className="ds-header__date">{formatDate(time)}</span>
                </div>
                <div className="ds-header__pill">
                    <span className="ds-header__pill-icon">📍</span>
                    <span>Store 112</span>
                </div>
                <div className="ds-header__pill">
                    <span className="ds-header__pill-icon">📦</span>
                    <span>1,248 Orders</span>
                </div>
            </div>
        </div>
    );
}
","/* Dark Store Intelligence Center - Global Styles */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

.ds-app {
    max-width: 1600px;
    margin: 0 auto;
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 24px;
    background: #0a0e1a;
    min-height: 100vh;
    color: #e2e8f0;
    font-family: system-ui, -apple-system, sans-serif;
}

/* Card base class */
.ds-card {
    background: #131a2e;
    border: 1px solid #1e2a45;
    border-radius: 14px;
    padding: 24px;
    box-shadow: 0 0 20px rgba(0, 200, 150, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

/* Section title */
.ds-section-title {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: #94a3b8;
    margin-bottom: 16px;
}

/* Row layouts */
.ds-row {
    display: grid;
    gap: 24px;
}

.ds-row--2col {
    grid-template-columns: 1fr 1fr;
}

.ds-row--3col {
    grid-template-columns: 1fr 1fr 1fr;
}

/* Badge styles */
.ds-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.5px;
}

.ds-badge--green {
    background: rgba(0, 200, 150, 0.12);
    color: #00c896;
    border: 1px solid rgba(0, 200, 150, 0.3);
}

.ds-badge--orange {
    background: rgba(245, 158, 11, 0.12);
    color: #f59e0b;
    border: 1px solid rgba(245, 158, 11, 0.3);
}

.ds-badge--red {
    background: rgba(239, 68, 68, 0.12);
    color: #ef4444;
    border: 1px solid rgba(239, 68, 68, 0.3);
}

.ds-badge--blue {
    background: rgba(59, 130, 246, 0.12);
    color: #3b82f6;
    border: 1px solid rgba(59, 130, 246, 0.3);
}

.ds-badge--purple {
    background: rgba(139, 92, 246, 0.12);
    color: #8b5cf6;
    border: 1px solid rgba(139, 92, 246, 0.3);
}

/* Progress bar base */
.ds-progress {
    height: 6px;
    background: rgba(30, 42, 69, 0.8);
    border-radius: 3px;
    overflow: hidden;
}

.ds-progress__fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.6s ease;
}

.ds-progress__fill--green {
    background: linear-gradient(90deg, #00c896, #00e6ac);
}

.ds-progress__fill--blue {
    background: linear-gradient(90deg, #3b82f6, #60a5fa);
}

.ds-progress__fill--orange {
    background: linear-gradient(90deg, #f59e0b, #fbbf24);
}

.ds-progress__fill--red {
    background: linear-gradient(90deg, #ef4444, #f87171);
}

/* Animations */
@keyframes ds-pulse {
    0%, 100% {
        opacity: 1;
        transform: scale(1);
    }
    50% {
        opacity: 0.5;
        transform: scale(1.3);
    }
}

@keyframes ds-fade-in {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes ds-blink {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: 0.6;
    }
}

@keyframes ds-gauge-fill {
    from {
        stroke-dashoffset: 565;
    }
}

.ds-app .fade-in {
    animation: ds-fade-in 0.4s ease-out forwards;
}

/* Scrollbar */
.ds-app ::-webkit-scrollbar {
    width: 6px;
}

.ds-app ::-webkit-scrollbar-track {
    background: #0a0e1a;
}

.ds-app ::-webkit-scrollbar-thumb {
    background: #1e2a45;
    border-radius: 3px;
}

/* Responsive */
@media (max-width: 1200px) {
    .ds-row--2col {
        grid-template-columns: 1fr;
    }
}
