","import React from 'react';
import './DsImpactStrip.css';

const metrics = [
    { icon: '📦', value: '1,248', label: "Today's Orders", color: '#3b82f6' },
    { icon: '✅', value: '1,186', label: 'Delivered', color: '#00c896' },
    { icon: '💰', value: '₹6.8L', label: 'Revenue', color: '#00c896' },
    { icon: '⚡', value: '8.2 min', label: 'Avg Delivery', color: '#3b82f6' },
    { icon: '⭐', value: '96%', label: 'CSAT Score', color: '#f59e0b' },
    { icon: '💚', value: '91', label: 'PulseScore', color: '#00c896' },
    { icon: '🔄', value: '99.8%', label: 'Store Uptime', color: '#00c896' },
];

export default function DsImpactStrip() {
    return (
        <div className="ds-impact ds-card">
            <div className="ds-impact__grid">
                {metrics.map((m, i) => (
                    <div key={i} className="ds-impact__item">
                        <span className="ds-impact__icon">{m.icon}</span>
                        <span className="ds-impact__value" style={{ color: m.color }}>{m.value}</span>
                        <span className="ds-impact__label">{m.label}</span>
                    </div>
                ))}
            </div>
        </div>
    );
}
