","import React from 'react';
import './DsPulseHero.css';

const factors = [
    { name: 'Delivery Performance', value: 94, color: '#00c896' },
    { name: 'Inventory Accuracy', value: 98, color: '#00c896' },
    { name: 'Equipment Health', value: 96, color: '#00c896' },
    { name: 'Staff Performance', value: 91, color: '#00c896' },
    { name: 'Complaint Rate', value: 88, color: '#f59e0b' },
    { name: 'SLA Compliance', value: 95, color: '#00c896' },
    { name: 'Refund Rate', value: 92, color: '#00c896' },
    { name: 'Partner Performance', value: 89, color: '#00c896' },
];

export default function DsPulseHero() {
    const score = 91;
    const circumference = 2 * Math.PI * 90;
    const offset = circumference - (score / 100) * circumference;

    return (
        <div className="ds-pulse-hero ds-card">
            <div className="ds-section-title">⚡ Store Health Index</div>
            <div className="ds-pulse-hero__grid">
                <div className="ds-pulse-hero__gauge-section">
                    <div className="ds-pulse-hero__gauge-wrapper">
                        <svg className="ds-pulse-hero__gauge" viewBox="0 0 200 200">
                            <circle
                                cx="100" cy="100" r="90"
                                fill="none"
                                stroke="#1e2a45"
                                strokeWidth="10"
                            />
                            <circle
                                cx="100" cy="100" r="90"
                                fill="none"
                                stroke="url(#pulseGradient)"
                                strokeWidth="10"
                                strokeLinecap="round"
                                strokeDasharray={circumference}
                                strokeDashoffset={offset}
                                transform="rotate(-90 100 100)"
                                className="ds-pulse-hero__gauge-fill"
                            />
                            <defs>
                                <linearGradient id="pulseGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                                    <stop offset="0%" stopColor="#00c896" />
                                    <stop offset="100%" stopColor="#00e6ac" />
                                </linearGradient>
                            </defs>
                        </svg>
                        <div className="ds-pulse-hero__gauge-center">
                            <span className="ds-pulse-hero__gauge-label">PulseScore™</span>
                            <span className="ds-pulse-hero__gauge-value">{score}</span>
                            <span className="ds-pulse-hero__gauge-badge">HEALTHY</span>
                        </div>
                    </div>
                    <div className="ds-pulse-hero__gauge-meta">
                        <span className="ds-pulse-hero__trend">▲ +4 Today</span>
                        <span className="ds-pulse-hero__desc">Composite Operational Health Index</span>
                    </div>
                </div>
                <div className="ds-pulse-hero__factors">
                    <div className="ds-pulse-hero__factors-title">Contributing Factors</div>
                    <div className="ds-pulse-hero__factors-list">
                        {factors.map((f, i) => (
                            <div key={i} className="ds-pulse-hero__factor">
                                <div className="ds-pulse-hero__factor-header">
                                    <span className="ds-pulse-hero__factor-check" style={{ color: f.color }}>✓</span>
                                    <span className="ds-pulse-hero__factor-name">{f.name}</span>
                                    <span className="ds-pulse-hero__factor-value" style={{ color: f.color }}>{f.value}%</span>
                                </div>
                                <div className="ds-progress">
                                    <div
                                        className="ds-progress__fill"
                                        style={{
                                            width: `${f.value}%`,
                                            background: `linear-gradient(90deg, ${f.color}, ${f.color}88)`,
                                        }}
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}
