","import React from 'react';
import './DsKpiCards.css';

const kpis = [
    {
        icon: '✅', label: 'Orders Completed', value: '1,186', trend: '+12%', trendUp: true,
        color: '#00c896', sparkline: '10,20,15,25,30,28,35,40,38,45',
    },
    {
        icon: '⏰', label: 'Late Deliveries', value: '12', trend: '-8%', trendUp: true,
        color: '#f59e0b', sparkline: '30,25,28,20,18,22,15,14,13,12',
    },
    {
        icon: '📊', label: 'Inventory Accuracy', value: '98.2%', trend: '+0.3%', trendUp: true,
        color: '#00c896', sparkline: '95,96,97,96,97,98,97,98,98,98',
    },
    {
        icon: '🔧', label: 'Equipment Health', value: '96%', trend: '+1%', trendUp: true,
        color: '#00c896', sparkline: '92,93,94,93,95,94,95,96,95,96',
    },
    {
        icon: '📝', label: 'Complaint Rate', value: '1.2%', trend: '-0.2%', trendUp: true,
        color: '#00c896', sparkline: '3,2.5,2.8,2.2,2,1.8,1.5,1.4,1.3,1.2',
    },
    {
        icon: '🏃', label: 'Avg Picking Time', value: '2.4 min', trend: '-0.3m', trendUp: true,
        color: '#3b82f6', sparkline: '4,3.5,3.2,3,2.8,2.9,2.7,2.5,2.5,2.4',
    },
];

function Sparkline({ data, color }: { data: string; color: string }) {
    const points = data.split(',').map(Number);
    const max = Math.max(...points);
    const min = Math.min(...points);
    const range = max - min || 1;
    const width = 60;
    const height = 24;

    const pathPoints = points
        .map((p, i) => {
            const x = (i / (points.length - 1)) * width;
            const y = height - ((p - min) / range) * height;
            return `${x},${y}`;
        })
        .join(' ');

    return (
        <svg width={width} height={height} className="ds-kpi__sparkline">
            <polyline
                points={pathPoints}
                fill="none"
                stroke={color}
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                opacity="0.7"
            />
        </svg>
    );
}

export default function DsKpiCards() {
    return (
        <div className="ds-kpi-section">
            <div className="ds-section-title">📈 Key Performance Indicators</div>
            <div className="ds-kpi__grid">
                {kpis.map((kpi, i) => (
                    <div key={i} className="ds-kpi ds-card">
                        <div className="ds-kpi__header">
                            <span className="ds-kpi__icon">{kpi.icon}</span>
                            <span className="ds-kpi__health-dot" style={{ background: kpi.color }}></span>
                        </div>
                        <div className="ds-kpi__value" style={{ color: kpi.color }}>{kpi.value}</div>
                        <div className="ds-kpi__label">{kpi.label}</div>
                        <div className="ds-kpi__footer">
                            <span className={`ds-kpi__trend ${kpi.trendUp ? 'ds-kpi__trend--up' : 'ds-kpi__trend--down'}`}>
                                {kpi.trendUp ? '▲' : '▼'} {kpi.trend}
                            </span>
                            <Sparkline data={kpi.sparkline} color={kpi.color} />
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
