import './DsStaffGrid.css';

const staff = [
    { name: 'Priya Sharma', orders: 142, pickTime: '2.1 min', errorRate: '0.8%', efficiency: 96, status: 'Working' },
    { name: 'Rahul Verma', orders: 128, pickTime: '2.3 min', errorRate: '1.1%', efficiency: 92, status: 'Working' },
    { name: 'Anita Patel', orders: 135, pickTime: '2.0 min', errorRate: '0.6%', efficiency: 97, status: 'Working' },
    { name: 'Vikram Singh', orders: 98, pickTime: '2.8 min', errorRate: '1.5%', efficiency: 84, status: 'Break' },
    { name: 'Deepika Nair', orders: 118, pickTime: '2.4 min', errorRate: '0.9%', efficiency: 91, status: 'Working' },
    { name: 'Amit Gupta', orders: 0, pickTime: '—', errorRate: '—', efficiency: 0, status: 'Offline' },
];

function MiniCircle({ value, color }: { value: number; color: string }) {
    const r = 14;
    const circ = 2 * Math.PI * r;
    const offset = circ - (value / 100) * circ;
    return (
        <svg width="36" height="36" className="ds-staff__circle">
            <circle cx="18" cy="18" r={r} fill="none" stroke="#1e2a45" strokeWidth="3" />
            <circle
                cx="18" cy="18" r={r}
                fill="none" stroke={color} strokeWidth="3"
                strokeLinecap="round"
                strokeDasharray={circ} strokeDashoffset={offset}
                transform="rotate(-90 18 18)"
            />
            <text x="18" y="18" textAnchor="middle" dominantBaseline="central"
                fill={color} fontSize="9" fontWeight="700">
                {value}
            </text>
        </svg>
    );
}

export default function DsStaffGrid() {
    return (
        <div className="ds-staff ds-card">
            <div className="ds-section-title">👥 Staff Performance</div>
            <div className="ds-staff__grid">
                {staff.map((s, i) => {
                    const statusColor = s.status === 'Working' ? 'green' : s.status === 'Break' ? 'orange' : 'red';
                    const effColor = s.efficiency >= 90 ? '#00c896' : s.efficiency >= 80 ? '#f59e0b' : '#64748b';
                    return (
                        <div key={i} className="ds-staff__card">
                            <div className="ds-staff__card-header">
                                <span className="ds-staff__name">{s.name}</span>
                                <span className={`ds-badge ds-badge--${statusColor}`}>{s.status}</span>
                            </div>
                            <div className="ds-staff__card-body">
                                <div className="ds-staff__stats">
                                    <div className="ds-staff__stat">
                                        <span className="ds-staff__stat-value">{s.orders}</span>
                                        <span className="ds-staff__stat-label">Orders</span>
                                    </div>
                                    <div className="ds-staff__stat">
                                        <span className="ds-staff__stat-value">{s.pickTime}</span>
                                        <span className="ds-staff__stat-label">Pick Time</span>
                                    </div>
                                    <div className="ds-staff__stat">
                                        <span className="ds-staff__stat-value">{s.errorRate}</span>
                                        <span className="ds-staff__stat-label">Error Rate</span>
                                    </div>
                                </div>
                                <MiniCircle value={s.efficiency} color={effColor} />
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
