","import React from 'react';
import './DsComplaints.css';

const categories = [
    { name: 'Late Delivery', pct: 35, count: 42, color: '#ef4444' },
    { name: 'Missing Items', pct: 25, count: 30, color: '#f59e0b' },
    { name: 'Damaged', pct: 15, count: 18, color: '#f97316' },
    { name: 'Wrong Item', pct: 12, count: 14, color: '#8b5cf6' },
    { name: 'Quality', pct: 8, count: 10, color: '#3b82f6' },
    { name: 'Other', pct: 5, count: 6, color: '#64748b' },
];

export default function DsComplaints() {
    const radius = 60;
    const circumference = 2 * Math.PI * radius;
    let cumulativeOffset = 0;

    return (
        <div className="ds-complaints ds-card">
            <div className="ds-section-title">📝 Complaint Breakdown</div>
            <div className="ds-complaints__content">
                <div className="ds-complaints__chart-wrapper">
                    <svg width="160" height="160" viewBox="0 0 160 160">
                        {categories.map((cat, i) => {
                            const segmentLength = (cat.pct / 100) * circumference;
                            const offset = circumference - segmentLength;
                            const rotation = (cumulativeOffset / circumference) * 360 - 90;
                            cumulativeOffset += segmentLength;
                            return (
                                <circle
                                    key={i}
                                    cx="80" cy="80" r={radius}
                                    fill="none"
                                    stroke={cat.color}
                                    strokeWidth="20"
                                    strokeDasharray={`${segmentLength} ${circumference - segmentLength}`}
                                    transform={`rotate(${rotation} 80 80)`}
                                    opacity="0.85"
                                />
                            );
                        })}
                        <text x="80" y="75" textAnchor="middle" fill="#e2e8f0" fontSize="18" fontWeight="800">120</text>
                        <text x="80" y="95" textAnchor="middle" fill="#94a3b8" fontSize="10" fontWeight="600">TOTAL</text>
                    </svg>
                </div>
                <div className="ds-complaints__legend">
                    {categories.map((cat, i) => (
                        <div key={i} className="ds-complaints__legend-item">
                            <span className="ds-complaints__legend-dot" style={{ background: cat.color }}></span>
                            <span className="ds-complaints__legend-name">{cat.name}</span>
                            <span className="ds-complaints__legend-pct" style={{ color: cat.color }}>{cat.pct}%</span>
                            <span className="ds-complaints__legend-count">({cat.count})</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
